package com.example.smartpantry;
import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.example.smartpantry.data.DatabaseHelper;import java.util.*;
public class RecipeDetailActivity extends AppCompatActivity{@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_detail);DatabaseHelper db=new DatabaseHelper(this);long id=getIntent().getLongExtra("id",-1);((TextView)findViewById(R.id.recipeTitle)).setText(getIntent().getStringExtra("name"));List<String> items=db.getIngredients(id);StringBuilder ing=new StringBuilder();for(String x:items)ing.append("• ").append(x).append("\n");((TextView)findViewById(R.id.ingredientsText)).setText(ing.toString());((TextView)findViewById(R.id.stepsText)).setText(getIntent().getStringExtra("steps"));}}
